ucs.kql:
// Turla LightNeuron — Transport Agent DLL/TLB drops + Install-TransportAgent PS
let KnownInstallers = dynamic(["trustedinstaller.exe","msiexec.exe","setup.exe","microsoft.exchange.setup.windowsinstaller.exe","umworkerprocess.exe","servicehub.exe"]);
let TransportFiles =
    DeviceFileEvents
    | where Timestamp > ago(30d)
    | where ActionType in ("FileCreated","FileModified","FileRenamed")
    | where FolderPath has_any (@"\TransportRoles\agents\", @"\Exchange Server\V15\TransportRoles\", @"\Exchange Server\V14\TransportRoles\")
    | where FileName endswith ".dll" or FileName endswith ".tlb" or FileName =~ "EdgeTransport.exe.config" or FileName =~ "winex.tlb"
    | where not(tolower(InitiatingProcessFileName) in (KnownInstallers))
    | where InitiatingProcessAccountName !endswith "$";
let TransportAgentCmds =
    DeviceProcessEvents
    | where Timestamp > ago(30d)
    | where FileName in~ ("powershell.exe","pwsh.exe","ManagementShell.exe")
    | where ProcessCommandLine has_any ("Install-TransportAgent","Enable-TransportAgent","New-TransportAgent","Set-TransportConfig")
    | project Timestamp, DeviceName, AccountName, FileName, ProcessCommandLine, InitiatingProcessFileName;
TransportFiles
| project FileEventTime = Timestamp, DeviceName, FolderPath, FileName, SHA256, InitiatingProcessFileName, InitiatingProcessFolderPath, InitiatingProcessCommandLine, InitiatingProcessAccountName
| union (TransportAgentCmds | project FileEventTime = Timestamp, DeviceName, FolderPath = "<cmd>", FileName = "<cmd>", SHA256 = "", InitiatingProcessFileName = FileName, InitiatingProcessFolderPath = "", InitiatingProcessCommandLine = ProcessCommandLine, InitiatingProcessAccountName = AccountName)
| order by FileEventTime desc

